1  @PostMapping("/account/password")
2  public String changePassword(@RequestParam String newPassword,
3                               @RequestParam String csrfToken,
4                               HttpSession session) {
5    // CSRF 토큰: 전달값과 세션 저장값 비교 (MVC Interceptor로 자동 검사 권장)
6    String sessionToken = (String) session.getAttribute("CSRF_TOKEN");
7    if (sessionToken == null || !sessionToken.equals(csrfToken)) {
8      throw new SecurityException("유효하지 않은 요청");
9    }
